    H,W=len(g),len(g[0])
    import collections
    cnt=collections.Counter(v for r in g for v in r)
    bg=cnt.most_common(1)[0][0]
    m=[v for v in cnt if v!=bg and cnt[v]<2][0]
    d={(i,j) for i in range(H) for j in range(W) if g[i][j]==m}
    cs={j for i,j in d}; rs={i for i,j in d}; sd={i-j for i,j in d}; sc={i+j for i,j in d}
    out=[[g[i][j] for j in range(W)] for i in range(H)]
    if len(cs)==1:
        c=list(cs)[0]
        for i in range(H): out[i][c]=m
    elif len(rs)==1:
        r=list(rs)[0]
        for j in range(W): out[r][j]=m
    elif len(sd)==1:
        s=list(sd)[0]
        for i in range(H):
            for j in range(W):
                if i-j==s: out[i][j]=m
    else:
        c=list(sc)[0]
        for i in range(H):
            for j in range(W):
                if i+j==c: out[i][j]=m
    return out
